// Des: Tests for ru-page-walk: M2 gate end to end on the mock
// Flo: mock + temp db > seed/sitemap > run > assert counts, rows, logs
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const walk = @import("ru-page-walk.zig"); const inde = @import("st-page-inde.zig"); const fron = @import("qu-fron-main.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const vmock = @import("nt-vend-mock.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, srv: mock.Mock, dirz: []u8, dbzz: sqli.Db, aren: std.heap.ArenaAllocator, wlk: walk.Walk,
pub fn up(self: *Rig) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.wlk = walk.Walk.init(allo, std.testing.io, .{}, &self.dbzz, self.dirz, true); self.wlk.gapz = 0; self.wlk.base = 0; }
pub fn down(self: *Rig) void { self.wlk.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn url(self: *Rig, path: []const u8) []const u8 { var buf: [96]u8 = undefined; return self.aren.allocator().dupe(u8, self.srv.urlOf(&buf, path)) catch ""; } };
test "sitemap seeds, robots denies /private with a logged decision, JSON-LD wins over text" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const addz = try rig.wlk.walkSmap(rig.url("/")); try std.testing.expectEqual(@as(u32, 4), addz); const sum = try rig.wlk.walkRun(3); try std.testing.expectEqual(@as(u32, 3), sum.done); try std.testing.expectEqual(@as(u32, 1), sum.skip); try std.testing.expect(!sum.halt and !sum.incm); try std.testing.expect(try inde.pageGet(&rig.dbzz, rig.aren.allocator(), rig.url("/private")) == null); const rec2 = (try inde.recoGet(&rig.dbzz, rig.aren.allocator(), rig.url("/p2"))).?; try std.testing.expectEqualStrings("ldjs", rec2.kind); const rec1 = (try inde.recoGet(&rig.dbzz, rig.aren.allocator(), rig.url("/p1"))).?; try std.testing.expectEqualStrings("text", rec1.kind); try std.testing.expect(std.mem.indexOf(u8, rec1.body, "Item 1 page text") != null); var stmt = try rig.dbzz.prep("SELECT count(*) FROM logz WHERE robo LIKE 'deny: /private%';"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 1), stmt.colInt(0)); }
test "block page is rejected, retried, then lands in the DLQ; nothing stored" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{rig.url("/blockp")}); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 0), sum.done); try std.testing.expectEqual(@as(u32, 3), sum.blok); try std.testing.expectEqual(@as(i64, 1), sum.dead); try std.testing.expect(try inde.pageGet(&rig.dbzz, rig.aren.allocator(), rig.url("/blockp")) == null); const dead = try fron.fronDead(&rig.dbzz, rig.aren.allocator()); try std.testing.expectEqualStrings("bloc", dead[0].errz); }
test "poison URLs (non-text, loop) go straight to the DLQ without tripping the breaker" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{ rig.url("/img"), rig.url("/loop"), rig.url("/p1") }); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(i64, 2), sum.dead); try std.testing.expectEqual(@as(u32, 1), sum.done); try std.testing.expect(!sum.halt); }
test "breaker trips on a failure spike and halts the run" { var rig: Rig = undefined; try rig.up(); defer rig.down(); var indx: usize = 0; while (indx < 30) : (indx += 1) { var pbuf: [32]u8 = undefined; _ = try rig.wlk.walkSeed(&.{rig.url(try std.fmt.bufPrint(&pbuf, "/blockp?n={d}", .{indx}))}); } const sum = try rig.wlk.walkRun(null); try std.testing.expect(sum.halt); try std.testing.expect(sum.seen < 30); try std.testing.expect(try fron.fronCont(&rig.dbzz, 0) > 0); }
test "flaky host recovers after retries" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{rig.url("/flaky")}); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 1), sum.done); try std.testing.expectEqual(@as(u32, 2), sum.fail); try std.testing.expectEqual(@as(i64, 0), sum.dead); }
test "short run against a declared total is flagged incomplete" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{ rig.url("/p1"), rig.url("/p2"), rig.url("/p3") }); const sum = try rig.wlk.walkRun(5); try std.testing.expectEqual(@as(u32, 3), sum.uniq); try std.testing.expect(sum.incm); }
test "crash resume: a claimed URL is picked up again, never fetched twice into the store" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{rig.url("/p1")}); const due = try fron.fronDue(&rig.dbzz, rig.aren.allocator(), std.math.maxInt(i64), 5); try fron.fronLock(&rig.dbzz, due[0].urlz); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 1), sum.done); var stmt = try rig.dbzz.prep("SELECT count(*) FROM page;"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 1), stmt.colInt(0)); }
test "Retry-After holds the host before the retry" { var rig: Rig = undefined; try rig.up(); defer rig.down(); rig.wlk.conf.retr_cont_maxz = 2; _ = try rig.wlk.walkSeed(&.{rig.url("/e503")}); const t0 = std.Io.Clock.awake.now(std.testing.io).toMilliseconds(); const sum = try rig.wlk.walkRun(null); const used = std.Io.Clock.awake.now(std.testing.io).toMilliseconds() - t0; try std.testing.expect(used >= 900); try std.testing.expectEqual(@as(i64, 1), sum.dead); }
test "walker with the ladder: blocked page is rescued by the vendor inside free credits" { var rig: Rig = undefined; try rig.up(); defer rig.down(); var vmk = vmock.Mock.init(allo); defer vmk.deinit(); vmk.rules = &.{.{ .has = "blockp", .minm = .rend }}; rig.wlk.conf.vend_free_cred = .{ .deco = 50, .zenr = 50, .brig = 50 }; rig.wlk.back = vmk.backend(); _ = try rig.wlk.walkSeed(&.{ rig.url("/blockp"), rig.url("/p1") }); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 2), sum.done); try std.testing.expectEqual(@as(usize, 2), vmk.calls.items.len); try std.testing.expect(!sum.halt); }
test "walker with the ladder: no free credits and no go stops the run instead of burning retries" { var rig: Rig = undefined; try rig.up(); defer rig.down(); var vmk = vmock.Mock.init(allo); defer vmk.deinit(); rig.wlk.back = vmk.backend(); _ = try rig.wlk.walkSeed(&.{ rig.url("/blockp"), rig.url("/blockp?n=2"), rig.url("/blockp?n=3") }); const sum = try rig.wlk.walkRun(null); try std.testing.expect(sum.halt); try std.testing.expectEqual(@as(usize, 0), vmk.calls.items.len); try std.testing.expectEqual(@as(u32, 1), sum.seen); }
test "walkRevi puts due pages back in the queue" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.wlk.walkSeed(&.{rig.url("/p1")}); _ = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 0), try rig.wlk.walkRevi(10)); try rig.dbzz.exec("UPDATE page SET next=0;"); try std.testing.expectEqual(@as(u32, 1), try rig.wlk.walkRevi(10)); const sum = try rig.wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 1), sum.done); }
